const app = document.querySelector('#app');

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text) node.textContent = text;
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  return node;
}
async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}
function alertMessage(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p', '', { role: 'alert' });
    app.append(alert);
  }
  alert.textContent = message;
}
function projectRow(project, onUpdate) {
  const row = element('div', '', { 'data-testid': 'project-row', class: 'project-row' });
  const open = element('button', 'Open project', { type: 'button' });
  open.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
  const archive = element('button', project.archived ? 'Restore project' : 'Archive project', { type: 'button' });
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      onUpdate(saved);
      app.querySelector('[role="alert"]')?.remove();
    } catch (error) { alertMessage(error.message); }
    finally { archive.disabled = false; }
  });
  row.append(element('span', project.name),
    element('span', `${project.completed}/${project.total} completed`, { 'data-testid': 'project-summary' }),
    open, archive);
  return row;
}
function renderRename(project, heading) {
  const form = element('form');
  const input = element('input', '', { id: 'new-project-name', type: 'text', autocomplete: 'off' });
  const rename = element('button', 'Rename project', { type: 'submit' });
  input.value = project.name;
  input.disabled = Boolean(project.archived);
  rename.disabled = Boolean(project.archived);
  form.append(element('label', 'New project name', { for: 'new-project-name' }), input, rename);
  app.append(form);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (project.archived) return;
    const name = input.value.trim();
    if (!name) { alertMessage('Project name is required'); return; }
    rename.disabled = true;
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      project.name = saved.name;
      heading.textContent = saved.name;
      document.title = `${saved.name} — Workboard`;
      input.value = saved.name;
      app.querySelector('[role="alert"]')?.remove();
    } catch (error) { alertMessage(error.message); }
    finally { rename.disabled = Boolean(project.archived); }
  });
}
async function renderTasks(project) {
  const path = `/api/projects/${project.id}/tasks`;
  const archived = Boolean(project.archived);
  let tasks = [];
  const form = element('form');
  const input = element('input', '', { id: 'task-title', type: 'text', autocomplete: 'off' });
  const create = element('button', 'Create task', { type: 'submit' });
  form.append(element('label', 'Task title', { for: 'task-title' }), input, create);
  const filter = element('select', '', { id: 'task-filter' });
  for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', value, { value }));
  const filters = element('div', '', { class: 'task-filters' });
  filters.append(element('label', 'Task filter', { for: 'task-filter' }), filter);
  const list = element('section', '', { 'aria-label': 'Tasks' });
  app.append(form, filters, list);
  function draw() {
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'Open' && task.completed) continue;
      if (filter.value === 'Completed' && !task.completed) continue;
      const row = element('div', '', { 'data-testid': 'task-row', class: 'task-row' });
      const checkbox = element('input', '', { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
      checkbox.checked = task.completed;
      checkbox.disabled = archived;
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        try {
          const saved = await request(`${path}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          task.completed = saved.completed;
          app.querySelector('[role="alert"]')?.remove();
          draw();
        } catch (error) {
          checkbox.checked = task.completed;
          alertMessage(error.message);
        } finally { checkbox.disabled = false; }
      });
      const title = element('span', task.title);
      const renameForm = element('form');
      const renameInput = element('input', '', { id: `new-task-title-${task.id}`, type: 'text', autocomplete: 'off' });
      const rename = element('button', 'Rename task', { type: 'submit' });
      renameInput.value = task.title;
      renameInput.disabled = archived;
      rename.disabled = archived;
      renameForm.append(element('label', 'New task title', { for: renameInput.id }), renameInput, rename);
      renameForm.addEventListener('submit', async event => {
        event.preventDefault();
        if (archived) return;
        const newTitle = renameInput.value.trim();
        if (!newTitle) { alertMessage('Task title is required'); return; }
        rename.disabled = true;
        try {
          const saved = await request(`${path}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title: newTitle }),
          });
          task.title = saved.title;
          title.textContent = saved.title;
          checkbox.setAttribute('aria-label', `Complete ${saved.title}`);
          renameInput.value = saved.title;
          app.querySelector('[role="alert"]')?.remove();
        } catch (error) { alertMessage(error.message); }
        finally { rename.disabled = archived; }
      });
      const priority = element('select', '', { id: `task-priority-${task.id}` });
      for (const value of ['Low', 'Normal', 'High']) priority.append(element('option', value, { value }));
      priority.value = task.priority;
      priority.disabled = archived;
      priority.addEventListener('change', async () => {
        priority.disabled = true;
        try {
          const saved = await request(`${path}/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ priority: priority.value }),
          });
          task.priority = saved.priority;
          app.querySelector('[role="alert"]')?.remove();
        } catch (error) { alertMessage(error.message); }
        finally {
          priority.value = task.priority;
          priority.disabled = archived;
        }
      });
      row.append(checkbox, title, renameForm,
        element('label', 'Task priority', { for: priority.id }), priority);
      list.append(row);
    }
  }
  filter.addEventListener('change', draw);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    if (archived) return;
    const title = input.value.trim();
    if (!title) { alertMessage('Task title is required'); return; }
    create.disabled = true;
    try {
      tasks.push(await request(path, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
      }));
      draw();
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) { alertMessage(error.message); }
    finally { create.disabled = archived; }
  });
  create.disabled = true;
  try { tasks = await request(path); draw(); }
  catch (error) { alertMessage(error.message); }
  finally { create.disabled = archived; }
}
async function render() {
  const match = window.location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) {
    const back = element('button', 'Projects', { type: 'button', class: 'back' });
    back.addEventListener('click', () => { window.location.href = '/'; });
    app.append(back);
    try {
      const project = await request(`/api/projects/${match[1]}`);
      document.title = `${project.name} — Workboard`;
      const heading = element('h1', project.name);
      app.append(heading);
      if (project.archived) app.append(element('p', 'Archived project'));
      renderRename(project, heading);
      await renderTasks(project);
    } catch (error) { alertMessage(error.message); }
    return;
  }
  app.append(element('h1', 'Workboard'));
  const form = element('form');
  const label = element('label', 'Project name', { for: 'project-name' });
  const input = element('input', '', { id: 'project-name', name: 'name', type: 'text', autocomplete: 'off' });
  const create = element('button', 'Create project', { type: 'submit' });
  form.append(label, input, create);
  const list = element('section', '', { 'aria-label': 'Projects', class: 'projects' });
  const filter = element('select', '', { id: 'project-filter' });
  for (const value of ['Active', 'Archived']) filter.append(element('option', value, { value }));
  const filters = element('div', '', { class: 'task-filters' });
  filters.append(element('label', 'Project filter', { for: 'project-filter' }), filter);
  let projects = [];
  function drawProjects() {
    list.replaceChildren();
    for (const project of projects) {
      if (Boolean(project.archived) !== (filter.value === 'Archived')) continue;
      list.append(projectRow(project, saved => {
        projects = projects.map(item => item.id === saved.id ? saved : item);
        drawProjects();
      }));
    }
  }
  filter.addEventListener('change', drawProjects);
  app.append(form, filters, list);
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) { alertMessage('Project name is required'); return; }
    create.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
      });
      projects.push(project);
      drawProjects();
      input.value = '';
      app.querySelector('[role="alert"]')?.remove();
      input.focus();
    } catch (error) { alertMessage(error.message); }
    finally { create.disabled = false; }
  });
  create.disabled = true;
  try {
    projects = await request('/api/projects');
    drawProjects();
  } catch (error) { alertMessage(error.message); }
  finally { create.disabled = false; }
}
render();

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

test('projects and scoped tasks are validated, ordered, and persisted across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const port = 20000 + Math.floor(Math.random() * 20000);
  const base = `http://127.0.0.1:${port}`;
  // Start with the prior schema to exercise an in-place migration.
  const legacy = new DatabaseSync(join(directory, 'projects.sqlite'));
  legacy.exec('CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)');
  legacy.close();
  let child;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'projects.sqlite') },
      stdio: ['ignore', 'ignore', 'inherit'],
    });
    for (let attempt = 0; attempt < 100; attempt++) {
      try { if ((await fetch(`${base}/health`)).ok) return; } catch {}
      await new Promise(resolve => setTimeout(resolve, 50));
    }
    throw new Error('Server did not become healthy');
  }
  async function stop() {
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
    child = undefined;
  }
  async function create(name) {
    return fetch(`${base}/api/projects`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
    });
  }
  try {
    await start();
    const health = await fetch(`${base}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    const invalid = await create('   ');
    assert.equal(invalid.status, 400);
    assert.match((await invalid.json()).error, /Project name is required/);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    assert.equal(first.archived, 0);
    assert.equal(first.total, 0);
    assert.equal(first.completed, 0);
    const second = await (await create('Second project')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.equal((await fetch(`${base}/projects/${first.id}`)).status, 200);
    assert.match(await (await fetch(base)).text(), /id="app"/);
    const taskPath = `${base}/api/projects/${first.id}/tasks`;
    async function addTask(title) {
      return fetch(taskPath, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
      });
    }
    async function complete(projectId, taskId, completed) {
      return fetch(`${base}/api/projects/${projectId}/tasks/${taskId}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed }),
      });
    }
    const blankTask = await addTask(' \t ');
    assert.equal(blankTask.status, 400);
    assert.match((await blankTask.json()).error, /Task title is required/);
    assert.deepEqual(await (await fetch(taskPath)).json(), []);
    const taskResponse = await addTask('  First task  ');
    assert.equal(taskResponse.status, 201);
    const task = await taskResponse.json();
    assert.equal(task.title, 'First task');
    assert.equal(task.completed, false);
    assert.equal(task.priority, 'Normal');
    assert.equal(task.project_id, first.id);
    const secondTask = await (await addTask('Second task')).json();
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${second.id}/tasks`)).json(), []);
    assert.equal((await complete(second.id, task.id, true)).status, 404);
    assert.equal((await complete(first.id, task.id, 'true')).status, 400);
    assert.equal((await complete(first.id, task.id, true)).status, 200);
    task.completed = true;
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    async function prioritize(projectId, taskId, priority) {
      return fetch(`${base}/api/projects/${projectId}/tasks/${taskId}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ priority }),
      });
    }
    assert.equal(secondTask.priority, 'Normal');
    assert.equal((await prioritize(second.id, task.id, 'High')).status, 404);
    for (const invalid of ['Urgent', 'high', '', null, 1]) {
      assert.equal((await prioritize(first.id, task.id, invalid)).status, 400);
    }
    assert.equal((await prioritize(first.id, task.id, 'High')).status, 200);
    task.priority = 'High';
    assert.equal((await prioritize(first.id, secondTask.id, 'Low')).status, 200);
    secondTask.priority = 'Low';
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    async function renameTask(projectId, taskId, title) {
      return fetch(`${base}/api/projects/${projectId}/tasks/${taskId}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }),
      });
    }
    const blankRename = await renameTask(first.id, task.id, ' \t ');
    assert.equal(blankRename.status, 400);
    assert.match((await blankRename.json()).error, /Task title is required/);
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    assert.equal((await renameTask(second.id, task.id, 'Wrong project')).status, 404);
    const renamedTask = await renameTask(first.id, task.id, '  Renamed task  ');
    assert.equal(renamedTask.status, 200);
    task.title = 'Renamed task';
    assert.deepEqual(await renamedTask.json(), task);
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    first.total = 2;
    first.completed = 1;
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    async function rename(name) {
      return fetch(`${base}/api/projects/${first.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }),
      });
    }
    const invalidRename = await rename(' \t ');
    assert.equal(invalidRename.status, 400);
    assert.match((await invalidRename.json()).error, /Project name is required/);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    const renamed = await rename('  Renamed project  ');
    assert.equal(renamed.status, 200);
    first.name = 'Renamed project';
    assert.deepEqual(await renamed.json(), first);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    async function archive(archived) {
      return fetch(`${base}/api/projects/${first.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived }),
      });
    }
    assert.equal((await archive('true')).status, 400);
    assert.equal((await archive(true)).status, 200);
    first.archived = 1;
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    assert.equal((await rename('Forbidden rename')).status, 409);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    assert.equal((await renameTask(first.id, task.id, 'Forbidden title')).status, 409);
    assert.equal((await prioritize(first.id, task.id, 'Normal')).status, 409);
    assert.equal((await addTask('Forbidden')).status, 409);
    assert.equal((await complete(first.id, task.id, false)).status, 409);
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    await stop();
    await start();
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.equal((await fetch(`${base}/projects/${first.id}`)).status, 200);
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    assert.equal((await archive(false)).status, 200);
    first.archived = 0;
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    assert.equal((await rename(' Restored project ')).status, 200);
    first.name = 'Restored project';
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    const restoredRename = await renameTask(first.id, task.id, ' Restored task ');
    assert.equal(restoredRename.status, 200);
    task.title = 'Restored task';
    assert.deepEqual(await restoredRename.json(), task);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    assert.equal((await prioritize(first.id, task.id, 'Normal')).status, 200);
    task.priority = 'Normal';
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    const reopened = await complete(first.id, task.id, false);
    assert.equal((await reopened.json()).completed, false);
    task.completed = false;
    first.completed = 0;
    await stop();
    await start();
    assert.deepEqual(await (await fetch(taskPath)).json(), [task, secondTask]);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    assert.equal((await fetch(`${base}/api/projects/999999`)).status, 404);
  } finally {
    if (child) await stop();
    await rm(directory, { recursive: true, force: true });
  }
});
